import React, { useContext, useState } from 'react';
import { Link } from 'react-router-dom';
import HeaderPerfil from '../../components/HeaderPerfil'; 
import "../../components/perfil_admin.css"; 

import { AuthContext } from '../../context/AuthContext';
const API_URL = 'http://localhost:3001/api/usuarios';

export default function PerfilAdmin() {

        const { currentUser, logout, updateCurrentUser } = useContext(AuthContext);

        const [selectedFile, setSelectedFile] = useState(null);
        const [uploadMessage, setUploadMessage] = useState('');
        const [uploadError, setUploadError] = useState('');

    // Si el usuario no está cargado (aún cargando o deslogueado), mostrar un mensaje de carga.
    if (!currentUser) {
        return (
            <div>
                <p>Cargando datos del perfil...</p>
            </div>
        );
    }

    const handleFileChange = (event) => {
        setSelectedFile(event.target.files[0]);
        setUploadMessage('');
        setUploadError('');
    };

    const handleUpload = async () => {
        if (!selectedFile || !currentUser || !currentUser.id_usuario) {
            setUploadError('Debe seleccionar un archivo y estar logueado.');
            return;
        }

        const formData = new FormData();
        // 'profileImage' debe coincidir con el campo usado en multer.single('profileImage')
        formData.append('profileImage', selectedFile); 

        try {
            const response = await fetch(`${API_URL}/upload-image/${currentUser.id_usuario}`, {
                method: 'POST',
                body: formData, 
            });

            const data = await response.json();

            if (response.ok) {
                setUploadMessage('Imagen subida con éxito!');
                setUploadError('');
                setSelectedFile(null);
                
                // Usamos data.img_perfil (que es la respuesta del backend)
                updateCurrentUser({ ...currentUser, img_perfil: data.img_perfil }); 
            } else {
                setUploadError(data.message || data.error || 'Error al subir la imagen.');
                setUploadMessage('');
            }
        } catch (error) {
            console.error('Error en la subida:', error);
            setUploadError('Error de conexión o subida fallida.');
            setUploadMessage('');
        }
    };

    const baseUrl = API_URL.replace('/api/usuarios', '');
    const imageUrl = currentUser.img_perfil ? `${baseUrl}${currentUser.img_perfil}` : null;

    const nombreCompleto = `${currentUser.nom_1 || ''} ${currentUser.nom_2 || ''} ${currentUser.ape_1 || ''} ${currentUser.ape_2 || ''}`.trim();
    const identificacion = `${currentUser.t_doc || ''} ${currentUser.id_usuario || ''}`.trim();

    return (
        // En lugar de <main>, es común envolver toda la página en un div o fragmento
        <div className="perfil-page-container"> 
            
            {/* Usamos el componente Header importado */}
            <HeaderPerfil />

            <main>
                <section className="perfil-box"> {/* Este es el contenedor centrado */}
                    <div className="profile-card"> {/* La tarjeta principal de perfil */}
                        <h2>Perfil</h2>
                        
                        <div className="profile-content"> {/* Contenedor para info y foto */}
                            <div className="info">
                                <h4>
                                    <strong>Nombre de usuario</strong><br />
                                    <span className="dato">{nombreCompleto}</span>
                                </h4>

                                <h4>
                                    <strong>Correo electrónico</strong><br />
                                    <span className="dato">{currentUser.correo}</span>
                                </h4>

                                <h4>
                                    <strong>Número telefónico</strong><br />
                                    <span className="dato">{currentUser.telefono}</span>
                                </h4>

                                <h4>
                                    <strong>Identificación</strong><br />
                                    <span className="dato">{identificacion}</span>
                                </h4>
                            </div>

                            {/* Foto de perfil y rol */}
                            <div className="profile-picture">
                                {imageUrl ? (
                                    // Muestra la imagen si la ruta existe
                                    <img 
                                        src={imageUrl} 
                                        alt="Perfil" 
                                        className="profile-image-actual" 
                                    />
                                ) : (
                                    // Muestra vacio si no hay imagen
                                    <span className="placeholder-icon"></span> 
                                )}
                                <span className="user-role">{currentUser.rol || currentUser.nombre_rol || 'Usuario'}</span> 
                            </div>
                            
                            {/* Carga de Imagen */}
                            <div className="image-upload-section">
                                <h4>Cambiar Imagen de Perfil</h4>
                                <input 
                                    type="file" 
                                    accept="image/*" 
                                    onChange={handleFileChange} 
                                    className="file-input"
                                />
                                <button 
                                    onClick={handleUpload} 
                                    disabled={!selectedFile}
                                    className="btn rosa btn-upload" 
                                >
                                    Subir Imagen
                                </button>
                                {uploadMessage && <p style={{ color: 'green', margin: '5px 0' }}>{uploadMessage}</p>}
                                {uploadError && <p style={{ color: 'red', margin: '5px 0' }}>{uploadError}</p>}
                            </div>
                                <span className="user-role">{currentUser.rol || currentUser.nombre_rol || 'Usuario'}</span> 
                            </div>
                        </div>

                        {/* Acciones */}
                        <div className="actions-container">
                            <Link to="/cambiar_datos_a">
                                <button className="btn rosa">Cambiar datos</button>
                            </Link>

                            <Link to="/cambiar_contra3">
                                <button className="btn rosa">Cambiar contraseña</button>
                            </Link>
                            
                            <Link to="/" onClick={logout}> 
                                <button className="btn gris">Cerrar sesión</button>
                            </Link>
                        </div>
                </section>
            </main>
        </div>
    );
}
